  /* #6: @5 = roll(@1, @2, @4) */
  arg1[0]=w1;
  arg1[1]=wr2;
  arg1[2]=w4;
  res1[0]=w5;
  if (casadi_f1(arg1, res1, iw, w, 0)) return 1;
  /* #7: @6 = horzcat(@0, @5) */
  rr=w6;
  for (i=0, cs=w0; i<6; ++i) *rr++ = *cs++;
  for (i=0, cs=w5; i<240; ++i) *rr++ = *cs++;
